    const promoIntervalRef = useRef<NodeJS.Timeout | null>(null);
    const WA_NUMBER = "6281213094426";
    const [bgImage, setBgImage] = useState(CoverCity2);

    //------------------------FUNCTIONS------------------------//
    const startPromoAutoSlide = useCallback(() => {
        if (promoIntervalRef.current) {
            clearInterval(promoIntervalRef.current);
        }
        promoIntervalRef.current = setInterval(() => {
            setCurrentPromoSlide((prev) => (prev + 1) % promoSlides.length);
        }, 5000);
    }, [promoSlides.length]);
    const nextPromoSlide = useCallback(() => {
        setCurrentPromoSlide((prev) => (prev + 1) % promoSlides.length);
        startPromoAutoSlide();
    }, [promoSlides.length, startPromoAutoSlide]);
    const prevPromoSlide = useCallback(() => {
        setCurrentPromoSlide(
            (prev) => (prev - 1 + promoSlides.length) % promoSlides.length
        );
        startPromoAutoSlide();
    }, [promoSlides.length, startPromoAutoSlide]);
    useEffect(() => {
        startPromoAutoSlide();
        return () => {
            if (promoIntervalRef.current) {
                clearInterval(promoIntervalRef.current);
            }
        };
    }, [startPromoAutoSlide]);
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth >= 768) {
                setBgImage(CoverCity2); // desktop
            } else {
                setBgImage(CoverCity2Potrait); // mobile
            }
        };

        handleResize(); // set awal

        window.addEventListener("resize", handleResize);
        return () => window.removeEventListener("resize", handleResize);
    }, []);

